**script.js**

```javascript
document.addEventListener('DOMContentLoaded', function() {
    const inputText = document.getElementById('inputText');
    const exclusion1 = document.getElementById('exclusion1');
    const exclusion2 = document.getElementById('exclusion2');
    const exclusion3 = document.getElementById('exclusion3');
    const exclusion4 = document.getElementById('exclusion4');
    const exclusion5 = document.getElementById('exclusion5');
    const removeButton = document.getElementById('removeButton');
    const outputText = document.getElementById('outputText');
    const copyButton = document.getElementById('copyButton');

    removeButton.addEventListener('click', function() {
        const textosParaRemover = [
            exclusion1.value.trim(),
            exclusion2.value.trim(),
            exclusion3.value.trim(),
            exclusion4.value.trim(),
            exclusion5.value.trim()
        ].filter(text => text !== ''); // Remover strings vazias

        let texto = inputText.value;
        textosParaRemover.forEach(texto => {
            const regex = new RegExp(texto, 'gi');
            texto = texto.replace(regex, '');
        });

        outputText.textContent = texto;
    });

    copyButton.addEventListener('click', function() {
        outputText.select();
        document.execCommand('copy');
        alert('Texto copiado para a área de transferência!');
    });
});
```

